/**
 * 主入口：产出完整事实层 JSON。
 *
 * @param {object} o
 *   y,m,d,h,mi      出生钟表时间（北京时间）
 *   gender          '男' | '女'
 *   city            地名（仅展示）
 *   lonEast, lat    出生地经纬度（东经/北纬为正）
 *   basis           'solar'（真太阳时，默认）| 'clock'（钟表时）
 *   sensitivity     是否做基准敏感性检查，默认 true
 */
function buildFact(o) {
  const basis = o.basis === 'clock' ? 'clock' : 'solar';
  const primary = computeWith(o, basis);

  let sensitivity = null;
  if (o.sensitivity !== false && primary.bazi.timePillar.ambiguous) {
    const alt = computeWith(o, basis === 'solar' ? 'clock' : 'solar');
    sensitivity = basisSensitivity(primary, alt);
  } else if (o.sensitivity !== false) {
    sensitivity = {
      timePillarDiffers: false, dayPillarDiffers: false, flips: [],
      stable: true,
      note: '两种时间基准的时柱一致，无基准敏感性。',
    };
  }

  const { moment: mo, bazi, ziwei, astro, verify } = primary;

  // 历法层互证 —— 两个独立库（lunar-javascript / iztro）各自把公历转成农历。
  // 注意不要拿干支去比：两个体系的月柱定义本来就不同 ——
  //   八字月柱按【节气】（立春/惊蛰…分月）
  //   紫微月柱按【农历月】（正月=寅月）
  // 实测 1950-03-07 这类日期二者必然不同，那不是谁错了。
  // 真正能互证的是农历日期本身。实测 55/55 一致。
  const crossCheck = {
    lunarDate: {
      byLunarJs: bazi.lunarText,
      byIztro: ziwei.lunarDate,
      consistent: bazi.lunarText === ziwei.lunarDate,
    },
    monthPillarConvention: {
      bazi: bazi.pillars[1].gz,
      ziwei: (ziwei.chineseDate || '').split(' ')[1] || null,
      same: bazi.pillars[1].gz === ((ziwei.chineseDate || '').split(' ')[1] || null),
      note: '八字月柱按节气分月，紫微月柱按农历月分月，二者定义不同，'
          + '不一致属正常，不代表任一实现有误。',
    },
    consistent: bazi.lunarText === ziwei.lunarDate,
    note: bazi.lunarText === ziwei.lunarDate
      ? '农历日期经两个独立库（lunar-javascript / iztro）交叉验证一致，历法层可信'
      : '⚠ 两个库给出的农历日期不一致，说明有一方历法实现有误，此盘不可信',
  };

  return {
    schema: 'mingli.fact/1',
    generatedAt: new Date().toISOString(),

    input: {
      y: mo.clock.y, m: mo.clock.m, d: mo.clock.d, h: mo.clock.h, mi: mo.clock.mi,
      gender: o.gender || '男',
      city: o.city || null,
      lonEast: mo.lonEast, lat: mo.lat,
      basis: mo.basis,
    },

    time: {
      clock: mo.clock,
      solar: mo.solar,
      adopted: mo.adopted,
      offsetMinutes: mo.offsetMinutes,
      longitudeMinutes: mo.longitudeMinutes,
      eotMinutes: mo.eotMinutes,
      dayShift: mo.dayShift,
      clockText: moment.fmt(mo.clock),
      solarText: moment.fmt(mo.solar),
      adoptedText: moment.fmt(mo.adopted),
    },

    bazi,
    ziwei,
    astro,
    verify,
    sensitivity,
    crossCheck,

    caveats: [
      '事实层（四柱、星曜、天体位置）是确定性计算，可复现、可验证。',
      '解读层（十神取象、星曜性质、元素对应）是传统约定，不是实证校准的预测模型。',
      '印证的逻辑是比较三个独立推导路径是否收敛，提升的是"相对可信度"，不是"绝对准确性"。',
      '本服务不提供改命、化解、消灾类内容，也不对健康、法律、投资作具体决策建议。',
    ],
  };
}

module.exports = { buildFact, computeWith, basisSensitivity, clockToUTC };

'use strict';
/**
 * 时间基准解析
 * ============================================================
 * 【为什么需要单独一个模块】
 *
 * 命理排盘有两个时间口径：
 *   钟表时 —— 出生证/户口本上写的时间（北京时间，锚定 120°E 的平太阳时）
 *   真太阳时 —— 修正经度时差与均时差后的当地真实太阳时
 *
 * 传统上八字（子平法）多用真太阳时，紫微斗数多按钟表时定时辰。
 * 如果各排各的，就会出现：
 *   同一个人，八字算出的时柱是「庚寅」，紫微算出的是「辛卯」，
 *   两个体系在算【不同的盘】，那"印证"就毫无意义。
 *
 * 所以本模块把时间基准【显式化并统一】：先算出两个口径，
 * 挑一个作为 adopted，然后把同一个时刻交给所有体系。
 * 口径差异作为数据暴露出去（不藏起来），由上层决定怎么向用户说明。
 */

const astro = require('./astro.js');

/**
 * 均时差（分钟）= 真太阳时 − 平太阳时
 * Meeus ch.28：E = L0 − 0.0057183° − α☉
 *   L0 取 ch.25 的太阳几何平黄经。
 * 标定：四个已知锚点误差 < 0.05 分钟 ——
 *   2/11 −14.18 (期望 −14.2) / 5/14 +3.66 (3.7)
 *   7/26  −6.55 (−6.5)       / 11/3 +16.45 (16.4)
 */
function equationOfTime(jd) {
  const T = (jd - 2451545.0) / 36525;
  const L0 = astro.norm360(280.46646 + 36000.76983 * T + 0.0003032 * T * T);
  const eps = astro.obliquity(jd);
  const ra = astro.toEquatorial(astro.sunLongitude(jd), eps).ra;
  let e = L0 - 0.0057183 - ra;
  e = ((e + 180) % 360 + 360) % 360 - 180;
  return e * 4;
}

/** 把"年月日时分"按分钟平移，返回归一化后的时刻（正确处理跨日/跨月/跨年） */
function shiftMinutes(y, m, d, h, mi, deltaMinutes) {
  const base = Date.UTC(y, m - 1, d, h, mi);
  const t = new Date(base + Math.round(deltaMinutes) * 60000);
  return {
    y: t.getUTCFullYear(),
    m: t.getUTCMonth() + 1,
    d: t.getUTCDate(),
    h: t.getUTCHours(),
    mi: t.getUTCMinutes(),
    dayShift: Math.round((Date.UTC(t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate())
      - Date.UTC(y, m - 1, d)) / 86400000),
  };
}

/**
 * 解析出生时刻，产出两个口径 + 实际采用的那个。
 *
 * @param {object} o  { y,m,d,h,mi, lonEast, lat, basis }
 *   basis: 'solar'（真太阳时，默认）| 'clock'（钟表时）
 */
function resolveMoment(o) {
  const { y, m, d, h, mi = 0 } = o;
  const lonEast = o.lonEast ?? 120;
  const basis = o.basis === 'clock' ? 'clock' : 'solar';

  // 经度时差：(当地经度 − 120°) × 4 分钟
  const longitudeMinutes = (lonEast - 120) * 4;
  // 均时差：以钟表时刻对应的 UTC 求
  const jd = astro.julianDay(y, m, d, h + mi / 60 - 8);
  const eotMinutes = equationOfTime(jd);
  const offsetMinutes = longitudeMinutes + eotMinutes;

  const solar = shiftMinutes(y, m, d, h, mi, offsetMinutes);
  const clock = { y, m, d, h, mi, dayShift: 0 };

  const adopted = basis === 'solar' ? solar : clock;

  return {
    clock: { y: clock.y, m: clock.m, d: clock.d, h: clock.h, mi: clock.mi },
    solar: { y: solar.y, m: solar.m, d: solar.d, h: solar.h, mi: solar.mi },
    adopted: {
      y: adopted.y, m: adopted.m, d: adopted.d, h: adopted.h, mi: adopted.mi,
      basis, dayShift: adopted.dayShift,
    },
    offsetMinutes: +offsetMinutes.toFixed(1),
    longitudeMinutes: +longitudeMinutes.toFixed(1),
    eotMinutes: +eotMinutes.toFixed(1),
    basis,
    lonEast,
    lat: o.lat ?? 30,
    // 真太阳时是否跨了日 —— 跨日会让日柱整体移动一位，是重要信息
    dayShift: solar.dayShift,
    julianDayUT: jd,
  };
}

/** 时刻 → 展示字符串 */
const fmt = (t) => `${t.y}-${String(t.m).padStart(2, '0')}-${String(t.d).padStart(2, '0')} `
  + `${String(t.h).padStart(2, '0')}:${String(t.mi).padStart(2, '0')}`;

module.exports = { equationOfTime, shiftMinutes, resolveMoment, fmt };

